---
On iOS only, force the @formatjs/intl-datetimeformat polyfill + IANA data so formatToParts works, then override Dayjs.prototype.tz to derive the offset from formatToParts instead of the broken toLocaleString path.
Android keeps stock dayjs (full ICU), and the polyfill is required behind a Platform.OS === 'ios' check so it's dropped from the Android bundle.

```
    "react-native": "0.83.6",
    "dayjs": "^1.11.19",
    "expo": "~55.0.24",
    "@formatjs/intl-datetimeformat": "^7.4.9",
    "@formatjs/intl-getcanonicallocales": "^3.2.10",
    "@formatjs/intl-locale": "^5.3.9",
```

something like `src/utils/dayjs.ts`
```
import dayjs from 'dayjs'
import 'dayjs/locale/en'
import 'dayjs/locale/es'
import advancedFormat from 'dayjs/plugin/advancedFormat'
import customParseFormat from 'dayjs/plugin/customParseFormat'
import localeData from 'dayjs/plugin/localeData'
import localizedFormat from 'dayjs/plugin/localizedFormat'
import relativeTime from 'dayjs/plugin/relativeTime'
import timezone from 'dayjs/plugin/timezone'
import utc from 'dayjs/plugin/utc'
import { Platform } from 'react-native'

dayjs.extend(utc)
dayjs.extend(timezone)
dayjs.extend(localeData)
dayjs.extend(relativeTime)
dayjs.extend(advancedFormat)
dayjs.extend(localizedFormat)
dayjs.extend(customParseFormat)

// iOS-only timezone fix. Android's Hermes is built against full ICU, so
// Intl.DateTimeFormat honors the `timeZone` option natively and dayjs.tz() works.
// iOS Hermes' Intl is Foundation-backed and ignores `timeZone` in formatToParts,
// so every .tz() call silently no-ops to UTC. We fix that on iOS only.
if (Platform.OS === 'ios') {
  // 1) Force the formatjs polyfill (with full IANA data) so formatToParts honors
  //    `timeZone`. require() (not import) keeps it out of the Android bundle.
  //    Order matters: DateTimeFormat depends on Intl.getCanonicalLocales + Intl.Locale
  //    (which Hermes doesn't provide), so those non-force polyfills load first.
  /* eslint-disable @typescript-eslint/no-require-imports */
  require('@formatjs/intl-getcanonicallocales/polyfill.js')
  require('@formatjs/intl-locale/polyfill.js')
  require('@formatjs/intl-datetimeformat/polyfill-force.js')
  require('@formatjs/intl-datetimeformat/locale-data/en.js')
  require('@formatjs/intl-datetimeformat/add-all-tz.js')
  /* eslint-enable @typescript-eslint/no-require-imports */

  // 2) dayjs's bundled instance `.tz()` computes the offset via
  //    Date.prototype.toLocaleString, which the polyfill returns date-only for (and is
  //    host-zone dependent + buggy across date boundaries). Override it to derive the
  //    offset from formatToParts (now correct) and apply it with utcOffset(). This fixes
  //    every existing `.tz()` call site at one chokepoint. Static dayjs.tz() already
  //    uses formatToParts internally and is left as-is.
  const zoneOffsetMinutes = (ms: number, zone: string): number => {
    const date = new Date(ms)
    const parts = new Intl.DateTimeFormat('en-US', {
      timeZone: zone,
      hourCycle: 'h23',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    }).formatToParts(date)
    const p: Record<string, string> = {}
    for (const { type, value } of parts) if (type !== 'literal') p[type] = value
    const asUTC = Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour % 24, +p.minute, +p.second)
    return (asUTC - date.getTime()) / 60000
  }

  dayjs.extend((_option, Dayjs, dayjsFactory) => {
    // `$x` is dayjs's internal per-instance state (holds `$timezone`); not in the types.
    const tagZone = (ins: dayjs.Dayjs, tz: string) => {
      const x = ins as unknown as { $x: Record<string, unknown> }
      x.$x = { ...x.$x, $timezone: tz }
      return ins
    }
    Dayjs.prototype.tz = function (zone, keepLocalTime) {
      const tz = zone || dayjsFactory.tz.guess()
      if (keepLocalTime) {
        // Reinterpret this instance's wall-clock as `tz`-local and resolve the instant.
        // Use the offset at the current instant, then correct once for DST edges.
        const guess = zoneOffsetMinutes(this.valueOf(), tz)
        let ins = this.utcOffset(guess, true)
        const real = zoneOffsetMinutes(ins.valueOf(), tz)
        if (real !== guess) ins = this.utcOffset(real, true)
        return tagZone(ins, tz)
      }
      return tagZone(this.utcOffset(zoneOffsetMinutes(this.valueOf(), tz)), tz)
    }
  })
}

// console.log(
//   '🕐 TZ CHECK ~ 12:15Z in America/Chicago should be 7:15 AM:',
//   dayjs('2026-06-25T12:15:00.000Z').tz('America/Chicago').format('LT')
// )

export { dayjs }

```

